typedef struct {
  char name[120];
  int count;
  int parent;
} Person;

static int findRoot(Person *people, int i) {
  while (people[i].parent != i) {
    people[i].parent = people[people[i].parent].parent;
    i = people[i].parent;
  }
  return i;
}

static int indexOf(Person *people, int n, const char *name) {
  for (int i = 0; i < n; i++) {
    if (strcmp(people[i].name, name) == 0) return i;
  }
  return -1;
}

static int cmpStr(const void *a, const void *b) {
  return strcmp(*(char **)a, *(char **)b);
}

char **trulyMostPopular(char **names, int namesSize, char **synonyms, int synonymsSize, int *returnSize) {
  static Person people[20000];
  int n = 0;
  for (int i = 0; i < namesSize; i++) {
    char name[120];
    int cnt;
    sscanf(names[i], "%[^(](%d)", name, &cnt);
    strcpy(people[n].name, name);
    people[n].count = cnt;
    people[n].parent = n;
    n++;
  }
  for (int i = 0; i < synonymsSize; i++) {
    char a[120], b[120];
    sscanf(synonyms[i], "(%[^,],%[^)])", a, b);
    if (indexOf(people, n, a) < 0) {
      strcpy(people[n].name, a);
      people[n].count = 0;
      people[n].parent = n;
      n++;
    }
    if (indexOf(people, n, b) < 0) {
      strcpy(people[n].name, b);
      people[n].count = 0;
      people[n].parent = n;
      n++;
    }
  }
  for (int i = 0; i < synonymsSize; i++) {
    char a[120], b[120];
    sscanf(synonyms[i], "(%[^,],%[^)])", a, b);
    int ra = findRoot(people, indexOf(people, n, a));
    int rb = findRoot(people, indexOf(people, n, b));
    if (ra != rb) {
      if (strcmp(people[ra].name, people[rb].name) < 0) {
        people[rb].parent = ra;
      } else {
        people[ra].parent = rb;
      }
    }
  }
  int agg[20000] = {0};
  for (int i = 0; i < n; i++) {
    agg[findRoot(people, i)] += people[i].count;
  }
  char **res = (char **)malloc(sizeof(char *) * n);
  int size = 0;
  for (int i = 0; i < n; i++) {
    if (agg[i] > 0) {
      res[size] = (char *)malloc(160);
      sprintf(res[size], "%s(%d)", people[i].name, agg[i]);
      size++;
    }
  }
  qsort(res, size, sizeof(char *), cmpStr);
  *returnSize = size;
  return res;
}

class Solution {
  string root(map<string, string> &parent, map<string, int> &rank, string x) {
    if (parent.find(x) == parent.end()) {
      parent[x] = x;
      rank[x] = 0;
    }
    if (parent[x] != x) parent[x] = root(parent, rank, parent[x]);
    return parent[x];
  }

  void unite(map<string, string> &parent, map<string, int> &rank, string a, string b) {
    string ra = root(parent, rank, a), rb = root(parent, rank, b);
    if (ra == rb) return;
    if (ra < rb) {
      parent[rb] = ra;
    } else {
      parent[ra] = rb;
    }
  }

public:
  vector<string> trulyMostPopular(vector<string> &names, vector<string> &synonyms) {
    map<string, string> parent;
    map<string, int> rank;
    map<string, int> freq;
    for (const string &s : names) {
      auto pos = s.find('(');
      string name = s.substr(0, pos);
      int cnt = stoi(s.substr(pos + 1, s.size() - pos - 2));
      freq[name] = cnt;
      root(parent, rank, name);
    }
    for (const string &s : synonyms) {
      auto pos = s.find(',');
      string a = s.substr(1, pos - 1);
      string b = s.substr(pos + 1, s.size() - pos - 2);
      unite(parent, rank, a, b);
    }
    map<string, int> agg;
    for (auto &kv : freq) {
      agg[root(parent, rank, kv.first)] += kv.second;
    }
    vector<string> res;
    for (auto &kv : agg) res.push_back(kv.first + "(" + to_string(kv.second) + ")");
    return res;
  }
};

func trulyMostPopular(names []string, synonyms []string) []string {
	parent := map[string]string{}
	freq := map[string]int{}
	var find func(x string) string
	find = func(x string) string {
		if _, ok := parent[x]; !ok {
			parent[x] = x
		}
		if parent[x] != x {
			parent[x] = find(parent[x])
		}
		return parent[x]
	}
	union := func(a, b string) {
		ra, rb := find(a), find(b)
		if ra == rb {
			return
		}
		if ra < rb {
			parent[rb] = ra
		} else {
			parent[ra] = rb
		}
	}
	for _, s := range names {
		pos := strings.Index(s, "(")
		name := s[:pos]
		cnt, _ := strconv.Atoi(s[pos+1 : len(s)-1])
		freq[name] = cnt
		find(name)
	}
	for _, s := range synonyms {
		inside := s[1 : len(s)-1]
		parts := strings.Split(inside, ",")
		union(parts[0], parts[1])
	}
	agg := map[string]int{}
	for name, cnt := range freq {
		agg[find(name)] += cnt
	}
	res := []string{}
	for name, cnt := range agg {
		res = append(res, name+"("+strconv.Itoa(cnt)+")")
	}
	sort.Strings(res)
	return res
}

class Solution {
  private Map<String, String> parent = new HashMap<>();

  private String find(String x) {
    parent.putIfAbsent(x, x);
    if (!parent.get(x).equals(x)) parent.put(x, find(parent.get(x)));
    return parent.get(x);
  }

  private void union(String a, String b) {
    String ra = find(a), rb = find(b);
    if (ra.equals(rb)) return;
    if (ra.compareTo(rb) < 0) parent.put(rb, ra);
    else parent.put(ra, rb);
  }

  public String[] trulyMostPopular(String[] names, String[] synonyms) {
    Map<String, Integer> freq = new HashMap<>();
    for (String s : names) {
      int pos = s.indexOf('(');
      String name = s.substring(0, pos);
      int cnt = Integer.parseInt(s.substring(pos + 1, s.length() - 1));
      freq.put(name, cnt);
      find(name);
    }
    for (String s : synonyms) {
      String[] parts = s.substring(1, s.length() - 1).split(",");
      union(parts[0], parts[1]);
    }
    Map<String, Integer> agg = new TreeMap<>();
    for (Map.Entry<String, Integer> e : freq.entrySet()) {
      String r = find(e.getKey());
      agg.put(r, agg.getOrDefault(r, 0) + e.getValue());
    }
    List<String> res = new ArrayList<>();
    for (Map.Entry<String, Integer> e : agg.entrySet()) {
      res.add(e.getKey() + "(" + e.getValue() + ")");
    }
    return res.toArray(new String[0]);
  }
}

class Solution:
    def trulyMostPopular(self, names: List[str], synonyms: List[str]) -> List[str]:
        parent = {}

        def find(x: str) -> str:
            parent.setdefault(x, x)
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(a: str, b: str):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

        freq = {}
        for s in names:
            pos = s.index("(")
            name = s[:pos]
            cnt = int(s[pos + 1:-1])
            freq[name] = cnt
            find(name)

        for s in synonyms:
            a, b = s[1:-1].split(",")
            union(a, b)

        agg = {}
        for name, cnt in freq.items():
            r = find(name)
            agg[r] = agg.get(r, 0) + cnt
        return ["{}({})".format(k, v) for k, v in sorted(agg.items())]

impl Solution {
  pub fn truly_most_popular(names: Vec<String>, synonyms: Vec<String>) -> Vec<String> {
    let mut parent: HashMap<String, String> = HashMap::new();
    fn find(parent: &mut HashMap<String, String>, x: &str) -> String {
      if !parent.contains_key(x) {
        parent.insert(x.to_string(), x.to_string());
      }
      let p = parent.get(x).unwrap().clone();
      if p != x {
        let r = find(parent, &p);
        parent.insert(x.to_string(), r.clone());
        r
      } else {
        p
      }
    }
    let mut freq: HashMap<String, i32> = HashMap::new();
    for s in &names {
      let pos = s.find('(').unwrap();
      let name = s[..pos].to_string();
      let cnt: i32 = s[pos + 1..s.len() - 1].parse().unwrap();
      freq.insert(name.clone(), cnt);
      find(&mut parent, &name);
    }
    for s in &synonyms {
      let inside = &s[1..s.len() - 1];
      let parts: Vec<&str> = inside.split(',').collect();
      let ra = find(&mut parent, parts[0]);
      let rb = find(&mut parent, parts[1]);
      if ra != rb {
        if ra < rb {
          parent.insert(rb, ra);
        } else {
          parent.insert(ra, rb);
        }
      }
    }
    let mut agg: HashMap<String, i32> = HashMap::new();
    for (name, cnt) in &freq {
      let r = find(&mut parent, name);
      *agg.entry(r).or_insert(0) += cnt;
    }
    let mut res: Vec<String> = agg
      .into_iter()
      .map(|(k, v)| format!("{}({})", k, v))
      .collect();
    res.sort();
    res
  }
}

const trulyMostPopular = (names: string[], synonyms: string[]): string[] => {
  const parent = new Map<string, string>();
  const find = (x: string): string => {
    if (!parent.has(x)) parent.set(x, x);
    if (parent.get(x) !== x) parent.set(x, find(parent.get(x)!));
    return parent.get(x)!;
  };
  const union = (a: string, b: string) => {
    const ra = find(a);
    const rb = find(b);
    if (ra === rb) return;
    if (ra < rb) parent.set(rb, ra);
    else parent.set(ra, rb);
  };
  const freq = new Map<string, number>();
  for (const s of names) {
    const pos = s.indexOf('(');
    const name = s.slice(0, pos);
    freq.set(name, parseInt(s.slice(pos + 1, -1)));
    find(name);
  }
  for (const s of synonyms) {
    const [a, b] = s.slice(1, -1).split(',');
    union(a, b);
  }
  const agg = new Map<string, number>();
  for (const [name, cnt] of freq) {
    const r = find(name);
    agg.set(r, (agg.get(r) ?? 0) + cnt);
  }
  return [...agg.keys()].sort().map((k) => `${k}(${agg.get(k)})`);
};
